ALTER TABLE public.search_keywords ADD COLUMN IF NOT EXISTS user_id uuid; UPDATE public.search_keywords SET user_id = (SELECT id FROM auth.users ORDER BY created_at LIMIT 1) WHERE user_id IS NULL; ALTER TABLE public.search_keywords ALTER COLUMN user_id SET NOT NULL; ALTER TABLE public.search_keywords ALTER COLUMN user_id SET DEFAULT auth.uid(); DROP POLICY IF EXISTS "auth read keywords" ON public.search_keywords; DROP POLICY IF EXISTS "auth write keywords" ON public.search_keywords; DROP POLICY IF EXISTS "auth update keywords" ON public.search_keywords; DROP POLICY IF EXISTS "auth delete keywords" ON public.search_keywords; CREATE POLICY "own keywords select" ON public.search_keywords FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY "own keywords insert" ON public.search_keywords FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "own keywords update" ON public.search_keywords FOR UPDATE TO authenticated USING (auth.uid() = user_id); CREATE POLICY "own keywords delete" ON public.search_keywords FOR DELETE TO authenticated USING (auth.uid() = user_id);